static String performLiteralSubstitution(final String input) {

        if (input == null) {
            return null;
        }

        StringBuilder strBuilder = null;

        boolean inLiteralSubstitution = false;
        boolean inLiteralSubstitutionInsertion = false;
        int literalSubstitutionIndex = -1;

        int expLevel = 0;
        boolean inLiteral = false;
        boolean inNothing = true;

        final int inputLen = input.length();
        for (int i = 0; i < inputLen; i++) {

            final char c = input.charAt(i);

            if (c == LITERAL_SUBSTITUTION_DELIMITER && !inLiteralSubstitution && inNothing) {

                if (strBuilder == null) {
                    strBuilder = new StringBuilder(inputLen + 20);
                    strBuilder.append(input,0,i);
                }
                inLiteralSubstitution = true;
                literalSubstitutionIndex = i;

            } else if (c == LITERAL_SUBSTITUTION_DELIMITER && inLiteralSubstitution && inNothing) {

                if ((i - literalSubstitutionIndex) == 1) {
                    // This was an empty literal substitution, which we are not going to process so that it
                    // cannot be used to mangle in the parsing, interpretation and validity checks of other
                    // expressions.
                    strBuilder
                            .append(LITERAL_SUBSTITUTION_DELIMITER)
                            .append(LITERAL_SUBSTITUTION_DELIMITER);
                } else if (inLiteralSubstitutionInsertion) {
                    strBuilder.append('\'');
                    inLiteralSubstitutionInsertion = false;
                }

                inLiteralSubstitution = false;
                literalSubstitutionIndex = -1;

            } else if (inNothing &&
                    (c == VariableExpression.SELECTOR ||
                            c == SelectionVariableExpression.SELECTOR ||
                            c == MessageExpression.SELECTOR ||
                            c == LinkExpression.SELECTOR) &&
                    (i + 1 < inputLen && input.charAt(i+1) == SimpleExpression.EXPRESSION_START_CHAR)) {
                // We are opening an expression

                if (inLiteralSubstitution && inLiteralSubstitutionInsertion) {
                    strBuilder.append("\' + ");
                    inLiteralSubstitutionInsertion = false;
                } else if (inLiteralSubstitution && i > 0 && input.charAt(i - 1) == SimpleExpression.EXPRESSION_END_CHAR) {
                    // This expression is right after another one, with no characters between them
                    strBuilder.append(" + \'\' + ");
                }

                if (strBuilder != null) {
                    strBuilder.append(c);
                    strBuilder.append(SimpleExpression.EXPRESSION_START_CHAR);
                }

                expLevel = 1;
                i++; // This avoids the following '{', which we already know is there, to increment expLevel twice
                inNothing = false;

            } else if (expLevel == 1 && c == SimpleExpression.EXPRESSION_END_CHAR) {
                // We are closing an expression

                if (strBuilder != null) {
                    strBuilder.append(SimpleExpression.EXPRESSION_END_CHAR);
                }

                expLevel = 0;
                inNothing = true;

            } else if (expLevel > 0 && c == SimpleExpression.EXPRESSION_START_CHAR) {
                // We are in an expression. This is needed for correct nesting/unnesting of expressions

                if (strBuilder != null) {
                    strBuilder.append(SimpleExpression.EXPRESSION_START_CHAR);
                }
                expLevel++;

            } else if (expLevel > 1 && c == SimpleExpression.EXPRESSION_END_CHAR) {
                // We are in an expression. This is needed for correct nesting/unnesting of expressions

                if (strBuilder != null) {
                    strBuilder.append(SimpleExpression.EXPRESSION_END_CHAR);
                }
                expLevel--;

            } else if (expLevel > 0) {
                // We are in an expression and not closing it, so just add the char

                if (strBuilder != null) {
                    strBuilder.append(c);
                }

            } else if (inNothing && !inLiteralSubstitution &&
                       c == TextLiteralExpression.DELIMITER && !TextLiteralExpression.isDelimiterEscaped(input, i)) {
                // We enter a first-level text literal. We should not process any |'s inside

                inNothing = false;
                inLiteral = true;

                if (strBuilder != null) {
                    strBuilder.append(c);
                }

            } else if (inLiteral && !inLiteralSubstitution &&
                       c == TextLiteralExpression.DELIMITER && !TextLiteralExpression.isDelimiterEscaped(input, i)) {

                inLiteral = false;
                inNothing = true;

                if (strBuilder != null) {
                    strBuilder.append(c);
                }

            } else if (inLiteralSubstitution && inNothing) {
                // This char is not starting an expresion, but it is inside a literal substitution, so add it
                // (and start an insertion if needed)

                if (!inLiteralSubstitutionInsertion) {
                    if (input.charAt(i - 1) != LITERAL_SUBSTITUTION_DELIMITER) {
                        strBuilder.append(" + ");
                    }
                    strBuilder.append('\'');
                    inLiteralSubstitutionInsertion = true;
                }

                if (c == TextLiteralExpression.DELIMITER) {
                    strBuilder.append('\\');
                } else if (c == TextLiteralExpression.ESCAPE_PREFIX) {
                    strBuilder.append('\\');
                }

                strBuilder.append(c);

            } else {
                // No literal substitution or anything. Just add the char

                if (strBuilder != null) {
                    strBuilder.append(c);
                }

            }

        }

        if (strBuilder == null) {
            return input;
        }

        return strBuilder.toString();

    }

public static void parseAttributeSequence(
            final char[] buffer,
            final int offset, final int len,
            final int line, final int col,
            final ITextHandler handler)
            throws TextParseException {

        // Any string will be recognized as an "attribute sequence", so this will always either return a not-null result
        // or raise an exception.

        final int maxi = offset + len;

        final int[] locator = new int[] {line, col};

        int i = offset;
        int current = i;

        int currentArtifactLine;
        int currentArtifactCol;

        while (i < maxi) {

            /*
             * STEP ONE: Look for whitespaces between attributes
             */

            final int wsEnd =
                    TextParsingUtil.findNextNonWhitespaceCharWildcard(buffer, i, maxi, locator);

            if (wsEnd == -1) {
                // Everything is whitespace until the end of the tag
                i = maxi;
                continue;
            }

            if (wsEnd > current) {
                // We avoid empty whitespace fragments
                i = wsEnd;
                current = i;
            }



            /*
             * STEP TWO: Detect the attribute name
             */


            currentArtifactLine = locator[0];
            currentArtifactCol = locator[1];

            final int attributeNameEnd =
                    TextParsingUtil.findNextOperatorCharWildcard(buffer, i, maxi, locator);

            if (attributeNameEnd == -1) {
                // This is a no-value and no-equals-sign attribute, equivalent to value = ""

                handler.handleAttribute(
                        buffer,                                                               // name
                        current, (maxi - current),                                            // name
                        currentArtifactLine, currentArtifactCol,                              // name
                        0, 0,                                                                 // operator
                        locator[0], locator[1],                                               // operator
                        0, 0, 0, 0,                                                           // value
                        locator[0], locator[1]);                                              // value

                i = maxi;
                continue;

            }

            if (attributeNameEnd <= current) {
                // This attribute name starts by an equals sign, which is forbidden
                throw new TextParseException(
                        "Bad attribute name in sequence \"" + new String(buffer, offset, len) + "\": attribute names " +
                        "cannot start with an equals sign", currentArtifactLine, currentArtifactCol);
            }


            final int attributeNameOffset = current;
            final int attributeNameLen = attributeNameEnd - current;
            final int attributeNameLine = currentArtifactLine;
            final int attributeNameCol = currentArtifactCol;
            i = attributeNameEnd;
            current = i;



            /*
             * STEP THREE: Detect the operator
             */


            currentArtifactLine = locator[0];
            currentArtifactCol = locator[1];

            final int operatorEnd =
                    TextParsingUtil.findNextNonOperatorCharWildcard(buffer, i, maxi, locator);

            if (operatorEnd == -1) {
                // This could be:
                //    1. A no-value and no-equals-sign attribute
                //    2. A no-value WITH equals sign attribute

                boolean equalsPresent = false;
                for (int j = i; j < maxi; j++) {
                    if (buffer[j] == '=') {
                        equalsPresent = true;
                        break;
                    }
                }

                if (equalsPresent) {
                    // It is a no value with equals, so we will consider everything
                    // to be an operator

                    handler.handleAttribute(
                            buffer,                                                                // name
                            attributeNameOffset, attributeNameLen,                                 // name
                            attributeNameLine, attributeNameCol,                                   // name
                            current, (maxi - current),                                             // operator
                            currentArtifactLine, currentArtifactCol,                               // operator
                            0, 0, 0, 0,                                                            // value
                            locator[0], locator[1]);                                               // value

                } else {
                    // There is no "=", so we will output the attribute with no operator and not value

                    handler.handleAttribute(
                            buffer,                                                                // name
                            attributeNameOffset, attributeNameLen,                                 // name
                            attributeNameLine, attributeNameCol,                                   // name
                            0, 0,                                                                  // operator
                            currentArtifactLine, currentArtifactCol,                               // operator
                            0, 0, 0, 0,                                                            // value
                            currentArtifactLine, currentArtifactCol);                              // value

                }

                i = maxi;
                continue;

                // end: (operatorEnd == -1)
            }


            boolean equalsPresent = false;
            for (int j = current; j < operatorEnd; j++) {
                if (buffer[j] == '=') {
                    equalsPresent = true;
                    break;
                }
            }

            if (!equalsPresent) {
                // It is not an operator, but a whitespace between this and the next attribute,
                // so we will output the attribute with no operator and no value

                handler.handleAttribute(
                        buffer,                                                                // name
                        attributeNameOffset, attributeNameLen,                                 // name
                        attributeNameLine, attributeNameCol,                                   // name
                        0, 0,                                                                  // operator
                        currentArtifactLine, currentArtifactCol,                               // operator
                        0, 0, 0, 0,                                                            // value
                        currentArtifactLine, currentArtifactCol);                              // value

                i = operatorEnd;
                current = i;
                continue;

            }


            final int operatorOffset = current;
            final int operatorLen = operatorEnd - current;
            final int operatorLine = currentArtifactLine;
            final int operatorCol = currentArtifactCol;
            i = operatorEnd;
            current = i;



            /*
             * STEP FOUR: Detect the value
             */


            currentArtifactLine = locator[0];
            currentArtifactCol = locator[1];

            final boolean attributeEndsWithQuotes = (i < maxi && (buffer[current] == '"' || buffer[current] == '\''));
            final int valueEnd =
                    (attributeEndsWithQuotes?
                            TextParsingUtil.findNextAnyCharAvoidQuotesWildcard(buffer, i, maxi, locator) :
                            TextParsingUtil.findNextWhitespaceCharWildcard(buffer, i, maxi, false, locator));

            if (valueEnd == -1) {
                // This value ends the attribute

                int valueContentOffset = current;
                int valueContentLen = (maxi - current);

                if (isValueSurroundedByCommas(buffer, current, (maxi - current))) {
                    valueContentOffset = valueContentOffset + 1;
                    valueContentLen = valueContentLen - 2;
                }

                handler.handleAttribute(
                        buffer,                                                               // name
                        attributeNameOffset, attributeNameLen,                                // name
                        attributeNameLine, attributeNameCol,                                  // name
                        operatorOffset, operatorLen,                                          // operator
                        operatorLine, operatorCol,                                            // operator
                        valueContentOffset, valueContentLen, current, (maxi - current),       // value
                        currentArtifactLine, currentArtifactCol);                             // value

                i = maxi;
                continue;

            }


            final int valueOuterOffset = current;
            final int valueOuterLen = valueEnd - current;
            int valueContentOffset = valueOuterOffset;
            int valueContentLen = valueOuterLen;

            if (isValueSurroundedByCommas(buffer, valueOuterOffset, valueOuterLen)) {
                valueContentOffset = valueOuterOffset + 1;
                valueContentLen = valueOuterLen - 2;
            }

            handler.handleAttribute(
                    buffer,                                                               // name
                    attributeNameOffset, attributeNameLen,                                // name
                    attributeNameLine, attributeNameCol,                                  // name
                    operatorOffset, operatorLen,                                          // operator
                    operatorLine, operatorCol,                                            // operator
                    valueContentOffset, valueContentLen, valueOuterOffset, valueOuterLen, // value
                    currentArtifactLine, currentArtifactCol);                             // value

            i = valueEnd;
            current = i;

        }

    }
